mapper.update:
update project
name = #{name}, priority = #{priority}, type = #{type}, pm = #{pmName}, status = #{status}, pm_id = #{pmId}, plan_start_date = #{planStartDate}, plan_end_date = #{planEndDate}, actual_start_date = #{actualStartDate}, actual_end_date = #{actualEndDate}, `desc` = #{desc}, modify_man = #{modifyMan}, modify_man_id = #{modifyManId},
id = #{id}

mapper.sql:
from project a
left join project_product_line b on a.id=b.project_id and b.is_deleted =false
left join product_line c on b.product_line_id=c.id
left join biz_domain d on c.biz_domain_id=d.id
left join person e on a.id=e.project_id and e.type =0 and e.is_deleted =false
left join person f on a.id=f.project_id and f.type =1 and f.is_deleted =false

    and a.id = #{id}
    and a.name like concat('%',#{name},'%')

        and a.plan_start_date >= #{planStartDateLeft} and a.plan_start_date <= #{planStartDateRight}


        and a.plan_end_date >= #{planEndDateLeft} and a.plan_end_date <= #{planEndDateRight}


        and a.actual_start_date >= #{actualStartDateLeft} and a.actual_start_date <= #{actualStartDateRight}


        and a.actual_end_date >= #{actualEndDateLeft} and a.actual_end_date <= #{actualEndDateRight}


        and a.modify_date >= #{modifyDateStart} and a.modify_date <= #{modifyDateEnd}




            and c.id in

                #{item}



            and d.id in

                #{item}



            and e.user_id in

                #{item}



            and f.user_id in

                #{item}




        and a.priority in

            #{item}



        and a.status in

            #{item}



        and a.type in

            #{item}



        and a.pm_id in

            #{item}


    and a.is_deleted =false

mapper.select:
select *from (select a.id,a.name, a.priority, a.type ,a.status,a.pm pmName,a.plan_start_date,a.plan_end_date, a.actual_start_date,a.actual_end_date,a.create_man,a.modify_date ,c.id cid,d.id did,e.user_id euser_id,f.user_id fuser_id ,group_concat(distinct c.name separator ',')productLineName ,group_concat(distinct d.name separator ',')bizDomainName ,group_concat(distinct e.user_name separator ',')pdName ,group_concat(distinct f.user_name separator ',')teamMember
group by a.id) a
and a.cid in
#{item}
and a.did in
#{item}
and a.euser_id in
#{item}
and a.fuser_id in
#{item}
order by a.modify_date desc limit #{offset},#{size}

select distinct p.id, p.name, p.priority, p.type, p.status, p.pm, p.pm_id, p.plan_start_date, p.plan_end_date, p.actual_start_date, p.actual_end_date, p.`desc`, p.is_deleted, p.create_man_id, p.create_man, p.create_date, p.modify_man_id, p.modify_man, p.modify_date from project_product_demand ppd join project p on ppd.project_id = p.id where ppd.is_deleted = false
and ppd.product_demand_id in
